"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import type { AnimationItem } from "lottie-web";


export type LuminaStudyProps = {
  className?: string;
  style?: CSSProperties;
  width?: number | string;
  paused?: boolean;
  loop?: boolean;
  /** Omit for a decorative illustration; set for meaningful content. */
  label?: string;
};

/** Plays the actual Lumina PH student animation through Lottie. */
export default function LuminaStudy({
  className,
  style,
  width = "100%",
  paused = false,
  loop = true,
  label,
}: LuminaStudyProps) {
  const container = useRef<HTMLDivElement>(null);
  const player = useRef<AnimationItem | null>(null);
  const pausedRef = useRef(paused);
  const reducedMotion = useRef(false);

  useEffect(() => {
    pausedRef.current = paused;
    if (paused || reducedMotion.current) player.current?.pause();
    else player.current?.play();
  }, [paused]);

  useEffect(() => {
    let disposed = false;
    let instance: AnimationItem | null = null;
    const preference = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedMotion.current = preference.matches;

    const updateMotion = () => {
      reducedMotion.current = preference.matches;
      if (preference.matches || pausedRef.current) instance?.pause();
      else instance?.play();
    };
    preference.addEventListener("change", updateMotion);

    // The browser-only player is loaded after mount for SSR compatibility.
    void import("lottie-web")
      .then(({ default: lottie }) => {
        if (disposed || !container.current) return;
        instance = lottie.loadAnimation({
          container: container.current,
          renderer: "svg",
          loop,
          autoplay: !pausedRef.current && !preference.matches,
          // Each mounted player receives its own animation object.
          animationData: JSON.parse(JSON.stringify(animationData)),
          rendererSettings: { preserveAspectRatio: "xMidYMid meet" },
        });
        player.current = instance;
      })
      .catch((error: unknown) => {
        if (!disposed) console.error("Lumina study animation could not load:", error);
      });

    return () => {
      disposed = true;
      preference.removeEventListener("change", updateMotion);
      instance?.destroy();
      if (player.current === instance) player.current = null;
    };
  }, [loop]);

  return (
    <div
      ref={container}
      className={className}
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      style={{ width, aspectRatio: "900 / 720", ...style }}
    />
  );
}


